<?php
require __DIR__.'/_layout.php';$u=require_admin();$pdo=db();$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();try{$a=$_POST['action']??'';
 if($a==='save_terms'){foreach(['team_registration_title','team_registration_intro','team_terms_version','term_name_respect','team_term_commitment','team_term_image','team_term_privacy'] as $k)set_setting($k,trim((string)($_POST[$k]??'')));go('equipe.php','Textos da ficha atualizados.');}
 if($a==='add_role'){if(!is_general_admin($u))throw new RuntimeException('Somente Admin Geral.');$name=mb_strtoupper(trim((string)$_POST['name']));$cat=mb_strtoupper(trim((string)$_POST['category']));if($name==='')throw new RuntimeException('Informe a função.');$pdo->prepare("INSERT INTO team_roles(name,category,active,sort_order,created_at) VALUES(?,?,1,?,?)")->execute([$name,$cat?:'EQUIPE',(int)($_POST['sort_order']??100),now_iso()]);go('equipe.php','Função adicionada.');}
 if($a==='edit_role'){if(!is_general_admin($u))throw new RuntimeException('Somente Admin Geral.');$id=(int)$_POST['role_id'];$name=mb_strtoupper(trim((string)$_POST['name']));$cat=mb_strtoupper(trim((string)$_POST['category']));$pdo->prepare("UPDATE team_roles SET name=?,category=?,active=?,sort_order=? WHERE id=?")->execute([$name,$cat?:'EQUIPE',isset($_POST['active'])?1:0,(int)$_POST['sort_order'],$id]);go('equipe.php','Função atualizada.');}
 if($a==='delete_role'){if(!is_general_admin($u))throw new RuntimeException('Somente Admin Geral.');$id=(int)$_POST['role_id'];$st=$pdo->prepare("SELECT COUNT(*) FROM team_members WHERE role_id=?");$st->execute([$id]);if((int)$st->fetchColumn()>0)throw new RuntimeException('A função já está vinculada a inscrições. Desative-a em vez de excluir.');$pdo->prepare("DELETE FROM team_roles WHERE id=?")->execute([$id]);go('equipe.php','Função excluída.');}
}catch(Throwable $e){$err=$e->getMessage();}}
$q=trim((string)($_GET['q']??''));$status=trim((string)($_GET['status']??''));$roleId=(int)($_GET['role_id']??0);$where=['tm.deleted_at IS NULL'];$params=[];
if($q!==''){$where[]='(tm.full_name LIKE ? OR tm.preferred_name LIKE ? OR tm.application_number LIKE ?)';$lk='%'.$q.'%';array_push($params,$lk,$lk,$lk);}
if($status!==''&&array_key_exists($status,team_statuses())){$where[]='tm.status=?';$params[]=$status;}
if($roleId>0){$where[]='tm.role_id=?';$params[]=$roleId;}
$st=$pdo->prepare("SELECT tm.*,tr.name role_name FROM team_members tm LEFT JOIN team_roles tr ON tr.id=tm.role_id WHERE ".implode(' AND ',$where)." ORDER BY tm.full_name COLLATE NOCASE");$st->execute($params);$rows=$st->fetchAll();$roles=team_roles(false);
admin_header('Equipe BAMAB — Inscrições e Crachás');$msg=flash();?>
<?php if($msg):?><div class="alert ok"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?>

