<div class="table-wrap"><table class="admin-table"><thead><tr><th>Nº</th><th>Foto</th><th>Nome</th><th>Como chamar</th><th>Função</th><th>Status</th><th>Crachá</th><th></th></tr></thead><tbody><?php foreach($rows as $rr):?><tr><td><strong><?=e($rr['application_number'])?></strong></td><td><?php if($rr['photo_path']):?><img class="admin-thumb-3x4" src="../<?=e($rr['photo_path'])?>" alt=""><?php endif;?></td><td><?=e($rr['full_name'])?></td><td><?=e($rr['preferred_name']?:'—')?></td><td><?=e($rr['role_name']?:'—')?></td><td><span class="status-pill"><?=e(team_status_label($rr['status']))?></span></td><td><span class="<?=$rr['badge_status']==='ATIVO'?'card-active':'card-inactive'?>"><?=e($rr['badge_status'])?></span></td><td><a class="small-button" href="equipe_ver.php?id=<?=$rr['id']?>">ABRIR</a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="empty-cell">Nenhuma inscrição.</td></tr><?php endif;?></tbody></table></div></section>

